import { IUploadedFile } from '../attachments/models/uploaded-file.model';

// Dto
import { ProfileDto } from './dto/profile.dto';
import { UpdateProfileDto } from './dto/update-profile.dto';

@Injectable()
export class UsersService extends BaseService<UserEntity> {

  constructor(
    @InjectRepository(UserEntity)
    private readonly userRepository: Repository<UserEntity>,
    private readonly attachmentsService: AttachmentsService
  ) {
    super(userRepository);
  }

  public async getProfile(id: number): Promise<ProfileDto> {
    try {
      const user = await this.findById(id, ['photo']);
      if (user) {
        const { password, ...userData} = user;
        return userData;
      }
    } catch (err) {
      console.log(err);
      throw new InternalServerErrorException();
    }
    throw new NotFoundException();
  }

  public async putProfile(userId: number, file: IUploadedFile, data: UpdateProfileDto): Promise<ProfileDto> {
    try {
      const photo = await this.attachmentsService.addAttachment(file);
      const user = await this.findById(userId);
      user.photo = photo;
      user.username = data.username;
      await this.update(userId, user);
      const {password, ...userData} = user;
      return userData;
    } catch (err) {
      console.log(err);
      throw new InternalServerErrorException();
    }
  }
}

import { Injectable, BadRequestException, Logger, NotFoundException } from '@nestjs/common'; 
import { GoalRepository } from './goal.repository';
import { InjectRepository } from '@nestjs/typeorm';
import { CreateGoalDto } from './dtos/create-goal.dto';
import { Goal } from './goal.entity';

@Injectable()
export class GoalService {
	private readonly logger = new Logger(GoalService.name);

	constructor(
		@InjectRepository(GoalRepository)
		private goalRepository: GoalRepository,
	) { }

	async update(id: string, goalDto: CreateGoalDto): Promise<Goal> {
		let goal: Goal = await this.goalRepository.findOne( { id: id } );

		if (this.goalDoesNotExist(goal)) {
			throw new NotFoundException(`Cannot find goal with id ${id}`);
		}

		return this.goalRepository.save( { id: id, ...goalDto } )
			.then( updated => {
				this.logger.log(`Goal ${id} was updated`);
				return updated;
			}).catch( error => {
				this.logger.error(`Error updating goal: ${error}`);
				throw new BadRequestException( error.message );
			});
	}

	private goalDoesNotExist(goal: Goal) {
		return !goal;
	}
}

import { Body, Controller, Delete, Get, Param, Post, Put } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { DeleteResult, Repository } from 'typeorm';
import { Profile } from './profile.entity';

@Controller('profiles')
export class ProfileController {
  constructor(
    @InjectRepository(Profile)
    private profileRepository: Repository<Profile>,
  ) {}

  @Get()
  async index(): Promise<Profile[]> {
    return this.profileRepository.find({order: {id: "ASC"}});
  }

  @Get(':id')
  async show(@Param('id') id: string): Promise<Profile> {
    return this.profileRepository.findOneOrFail(id);
  }

  @Post()
  async store(@Body() body: Profile): Promise<Profile> {
    const profile = this.profileRepository.create(body);
    return this.profileRepository.save(profile);
  }

  @Put(':id')
  async update(@Param('id') id: string, @Body() body: Profile): Promise<Profile> {
    await this.profileRepository.findOneOrFail(id);
    await this.profileRepository.update({id: +id}, body);
    return await this.profileRepository.findOneOrFail(id);
  }

  @Delete(':id')
  async destroy(@Param('id') id: string): Promise<DeleteResult> {
    await this.profileRepository.findOneOrFail(id);
    return this.profileRepository.delete(id);
  }
}

