    /// Find first subView of type
    func firstSubView<T: UIView>(ofType type: T.Type) -> T? {
        var resultView: T?

        for view in subviews {
            if let view = view as? T {
                resultView = view
                break
            } else {
                if let foundView = view.firstSubView(ofType: T.self) {
                    resultView = foundView
                    break
                }
            }
        }

        return resultView
    }

