Import trace for requested module:
../../packages/validation-schemas/src/index.ts


Here is the code used in the Next.js app:
import { zodResolver } from '@hookform/resolvers/zod';
import { useForm } from 'react-hook-form';
import {
    SchemaType,
    schema,
