w32 r1_get_file_id(const i4_const_str &fname) //retrieves the integer from an integer-form filename
{
	int x;
	char st[30], * s;

	s=st;

	i4_const_str::iterator l=fname.begin();
	while (l!=fname.end() && l.get().ascii_value()!='.')
	{
		*(s++)=l.get().ascii_value();
		++l;
	}

	*s=0;

	if (sscanf(st,"%x",&x))
	{
		return x;
	}
	else
	{
		return 0;
	}
}

