            foreach (var key in keys)
            {
                if (char.IsUpper(key[0]))
                {
                    StringBuilder camel = new StringBuilder(key);
                    camel[0] = Char.ToLowerInvariant(key[0]);
                    itemToUpdate[camel.ToString()] = itemToUpdate[key];
                    itemToUpdate.Remove(key);
                }
            }
        }

