        {
            List<string> keys = new List<string>();
            foreach (var point in GetEndPoints())
            {
                //获取指定服务器
                var server = GetServer(point);
                //在指定服务器使用keys或scan命令遍历key
                foreach (var key in server.Keys(_options.DefaultDB, "*"))
                {
                    if (!keys.Contains(key))
