        if (l > 2) {
            switch (Integer.parseInt("" + n.charAt(l - 3))) {
                case 3:
                    ret += "C";
                case 2:
                    ret += "C";
                case 1:
                    ret += "C";
                    break;
                case 4:
                    ret += "C";
                case 5:
                    ret += "D";
                    break;
                case 6:
                    ret += "DC";
                    break;
                case 7:
                    ret += "DCC";
                    break;
                case 8:
                    ret += "DCCC";
                    break;
                case 9:
                    ret += "CM";
                    break;
            }
        }
        if (l > 1) {
            switch (Integer.parseInt("" + n.charAt(l - 2))) {
                case 3:
                    ret += "X";
                case 2:
                    ret += "X";
                case 1:
                    ret += "X";
                    break;
                case 4:
                    ret += "X";
                case 5:
                    ret += "L";
                    break;
