                    ret += "LX";
                    break;
                case 7:
                    ret += "LXX";
                    break;
                case 8:
                    ret += "LXXX";
                    break;
                case 9:
                    ret += "XC";
                    break;
            }
        }
        if (l > 0) {
            switch (Integer.parseInt("" + n.charAt(l - 1))) {
                case 3:
                    ret += "I";
                case 2:
                    ret += "I";
                case 1:
                    ret += "I";
