template<typename T>
struct vec3 {
	T x, y, z;

	vec3(T x = 0) : x(x), y(x), z(x) {}
	vec3(T x, T y, T z) : x(x), y(y), z(z) {}
	template<typename S>
	vec3(const vec3<S> &v) : x(v.x), y(v.y), z(v.z) {}
	const float& operator[](const int i) const {
		switch (i) {
			case 0: return x;
			case 1: return y;
			case 2: return z;
			default: break;
		}
		throw std::runtime_error("Invalid index");
	}
	float& operator[](const int i) {
		switch (i) {
			case 0: return x;
			case 1: return y;
			case 2: return z;
			default: break;
		}
		throw std::runtime_error("Invalid index");
	}
};
