class Vector:
    """Represents a 2d cartesian vector"""

    def __init__(self, x=0, y=0):
        self.x = x
        self.y = y

    def mag(self):
        return sqrt(self.x*self.x + self.y*self.y)

    def __add__(self, other):
        if isinstance(other, Vector):
            return Vector(self.x + other.x, self.y + other.y)
        else:
            raise TypeError("Can only add a Vector to a Vector")

    def __sub__(self, other):
        if isinstance(other, Vector):
            return Vector(self.x - other.x, self.y - other.y)
        else:
            raise TypeError("Can only subtract a Vector from a Vector")

    def __eq__(self, other):
        if isinstance(other, Vector):
            return isclose(self.x, other.x) and isclose(self.y, other.y)
        else:
            return False

    def __ne__(self, other):
        return not self == other

    def __str__(self):
        return "(%f, %f)" % (self.x, self.y)

class Point(Vector):
    """Represents a 2d cartesian point"""

    def __init__(self, x=0, y=0):
        super().__init__(x, y)

    def __add__(self, other):
        if isinstance(other, Vector) and not isinstance(other, Point):
            return Point(self.x + other.x, self.y + other.y)
        else:
            return super().__add__(other)

    def __sub__(self, other):
        if isinstance(other, Vector) and not isinstance(other, Point):
            return Point(self.x - other.x, self.y - other.y)
        return super().__sub__(other)

class Point3:
    """A point in three-dimensional space."""
    def __init__(self, x=0, y=0, z=0):
        self.x=x
        self.y=y
        self.z=z

    def __repr__(self):
        return f"({self.x},{self.y},{self.z})"

    def __str__(self):
        return self.__repr__()

    def __add__(self, other):
        return Point3(self.x+other.x, self.y+other.y, self.z+other.z)

    def __sub__(self, other):
        return Point3(self.x-other.x, self.y-other.y, self.z-other.z)

    def __mul__(self, k):
        return Point3(k*self.x, k*self.y, k*self.z)

    def __neg__(self):
        return Point3(-self.x, -self.y, -self.z)

    def length(self):
        return (self.x**2+self.y**2+self.z**2)**0.5

    def normalize(self):
        s = 1/self.length()
        return Point3(s*self.x, s*self.y, s*self.z)

    def tuple(self):
        return (self.x, self.y, self.z)

    @staticmethod
    def dot(a,b):
        return a.x*b.x + a.y*b.y + a.z*b.z

    @staticmethod
    def cross(a,b):
        return Point3(a.y*b.z-a.z*b.y, a.z*b.x-a.x*b.z, a.x*b.y-a.y*b.x)

    @staticmethod
    def lerp(a,b,t):
        it = 1.0-t
        return Point3(it*a.x+t*b.x, it*a.y+t*b.y, it*a.z+t*b.z)

