    		case STRING:
                /* Must be an ArrayList */
    			prevSymbol();
            	ArrayList<Object> l1 = parseArrayList();
            	assert (currentSymbol.type == Type.BLOCK_END) : Type.BLOCK_END;
            	nextSymbol();
            	return l1;
    		case BLOCK_START:
    		case EQUALS:
                /* Its a HashMap */
    			prevSymbol();
            	HashMap<String, Object> map = parseHashMap();
            	assert (currentSymbol.type == Type.BLOCK_END) : Type.BLOCK_END;
            	nextSymbol();
                return map;
            default:
