    {
        for(coluna = 0; coluna < DIM; coluna++)
        {
            if(tabuleiro[linha][coluna] == 0)
                return 0;
            pecasJogador[tabuleiro[linha][coluna]]++;
        }
    }

    if (pecasJogador[0] > pecasJogador[1])
